import { spawnSync } from 'node:child_process';
import { existsSync } from 'node:fs';

// npm run supabase:start: the local Supabase stack. Its configuration (supabase/config.toml) is generated by `supabase init`, not
// committed, so a fresh clone had none and `supabase start` failed. Create it first when it is missing (CI runs `supabase init` itself).
const run = args => {
  const result = spawnSync('supabase', args, { stdio: 'inherit', shell: process.platform === 'win32' });
  if (result.status !== 0) process.exit(result.status ?? 1);
};
if (!existsSync(new URL('../supabase/config.toml', import.meta.url))) run(['init']);
run(['start', ...process.argv.slice(2)]);
